        content: "레나시딜액5 사용 후 두피 가려움, 비듬(인설), 홍반, 발적이 가장 흔하게 나타나요. 대부분 용매인 프로필렌글리콜이 원인이에요. 자극이 심하면 프로필렌글리콜 없는 폼 타입으로 교체하면 개선되는 경우가 많아요.\n\n도포 부위 이외에서 다모증(원치 않는 털 성장)이 나타날 수 있어요. 특히 여성은 안면 털 증가에 주의해야 해요. 모낭염, 작열감, 박리 같은 두피 자극도 드물게 보고돼요.\n\n흉통, 혈압 변화, 심박수 증가, 어지럼, 두통 같은 전신 반응은 드물지만 심각해요. 미녹시딜이 혈관 확장제이기 때문에 과도하게 흡수되면 전신에 영향을 줄 수 있어요. 이런 증상이 나타나면 즉시 레나시딜액5 사용을 중단하고 의사·약사와 상의하세요.",
