          "휴메리나정 0.5mg 30정의 기준가는 6000원이에요. 1정당으로 따지면 약 200원이고요. 두타스테리드 0.5mg 동일 성분 제품을 45개 비교한 가격 포지션에서 1정당 200원은 가장 낮은 구간에 속해요. 같은 성분군의 1정당 단가 범위가 200원부터 1267원까지 벌어져 있거든요. 같은 성분인데 차이가 꽤 커요. 어떤 제품을 고르느냐에 따라 부담이 달라지죠. 단가 200원 동률에는 케이두타다트정, 유힐릭스정도 30정 6000원으로 함께 들어가 있네요.\n\n다만 이 6000원은 실거래가가 아니라 기준가예요. 실제 구매가는 구매처와 처방 조건에 따라 달라질 수 있으니, 정확한 가격은 아래 버튼에서 확인해 보세요. 1정당 단가에 30을 곱하면 한 통, 다시 12를 곱하면 1년 치 윤곽이 잡혀요. 길게 먹는 약일수록 이 단가 한 칸이 전체 부담을 좌우하거든요.",
