        "content": "메가두타연질캡슐0.5밀리그램의 자체 수집 기준가는 30캡슐 한 통에 6,000원이에요. 통 단위로만 보면 부담이 잘 가늠되지 않으니 캡슐 하나 값으로 쪼개 볼게요. 6,000원을 30으로 나누면 한 캡슐에 약 200원이 떨어져요. 식약처에 오른 같은 두타스테리드 0.5mg 제품은 45개죠. 이 성분군에서 한 정 단가는 200원부터 1,267원까지 흩어져, 위아래 폭이 여섯 배에 달해요. 그 분포의 맨 아래 한 정 200원 자리에 메가두타연질캡슐이 들어가요. 캡슐인데도 최저가 정제와 한 알 값이 같으니, 비싼 동일성분 제품 기준 6분의 1 값인 셈이죠. 매일 길게 먹는 치료라 한 알 단가가 다달이 누적되는데, 200원이면 한 달 6,000원으로 끝나는 가벼운 부담이에요. 단, 전문의약품이라 별도 소비자가가 고시되지 않아 위 숫자는 기준가예요. 실거래가는 약국마다 다르니, 처방전을 받은 뒤 아래 버튼에서 확인하는 편이 정확해요."
