    heroDescription: "오리지널 아보다트가 연질캡슐인 것처럼, 다림두타스테리드연질캡슐도 대림바이오텍(주)에서 만든 연질캡슐 제형이에요. 두타스테리드 0.5mg이 오일에 용해돼 있어 흡수가 안정적이에요.",
    products: [],
